	'eudr.gate.title': { es: 'Aviso importante antes de usar esta herramienta', en: 'Important notice before using this tool', gn: 'Aviso importante antes de usar esta herramienta', pt: 'Aviso importante antes de usar esta ferramenta' },
	'eudr.gate.what.label': { es: 'Qué hace esta herramienta.', en: 'What this tool does.', gn: 'Qué hace esta herramienta.', pt: 'O que esta ferramenta faz.' },
	'eudr.gate.what': { es: 'Análisis satelital de pérdida forestal post-2020 (Hansen GFC {v} + MODIS de área quemada) sobre hexágonos de ~0,1 km² (H3 res-9). Cobertura: provincias del NEA argentino (Misiones, Corrientes, Chaco y Formosa), departamentos paraguayos y estados del sur de Brasil. Sirve para screening de riesgo EUDR, due-diligence preliminar y soporte técnico de informes. En Argentina (Misiones, Corrientes, Chaco y Formosa) distingue además la pérdida sobre <b>plantación forestal</b> (compatible con un ciclo de cosecha) de la <b>deforestación de bosque nativo</b>, cruzando con MapBiomas y un baseline al corte 2020.', en: 'Satellite analysis of post-2020 forest loss (Hansen GFC {v} + MODIS burned area) on ~0.1 km² hexagons (H3 res-9). Coverage: the Argentine NEA provinces (Misiones, Corrientes, Chaco and Formosa), Paraguayan departments and southern Brazilian states. It serves EUDR risk screening, preliminary due diligence and technical support for reports. In Argentina (Misiones, Corrientes, Chaco and Formosa) it also separates loss on <b>forest plantations</b> (consistent with a harvest cycle) from <b>native forest deforestation</b>, crossing with MapBiomas and a baseline at the 2020 cut-off.', gn: 'Análisis satelital de pérdida forestal post-2020 (Hansen GFC {v} + MODIS de área quemada) sobre hexágonos de ~0,1 km² (H3 res-9). Cobertura: provincias del NEA argentino (Misiones, Corrientes, Chaco y Formosa), departamentos paraguayos y estados del sur de Brasil. Sirve para screening de riesgo EUDR, due-diligence preliminar y soporte técnico de informes. En Argentina (Misiones, Corrientes, Chaco y Formosa) distingue además la pérdida sobre <b>plantación forestal</b> (compatible con un ciclo de cosecha) de la <b>deforestación de bosque nativo</b>, cruzando con MapBiomas y un baseline al corte 2020.', pt: 'Análise por satélite da perda florestal pós-2020 (Hansen GFC {v} + área queimada MODIS) em hexágonos de ~0,1 km² (H3 res-9). Cobertura: províncias do NEA argentino (Misiones, Corrientes, Chaco e Formosa), departamentos paraguaios e estados do sul do Brasil. Serve para triagem de risco EUDR, due diligence preliminar e suporte técnico a relatórios. Na Argentina (Misiones, Corrientes, Chaco e Formosa) distingue ainda a perda sobre <b>plantação florestal</b> (compatível com um ciclo de colheita) do <b>desmatamento de floresta nativa</b>, cruzando com o MapBiomas e uma linha de base no corte de 2020.' },
	'eudr.gate.scope.label': { es: 'Alcance regulatorio.', en: 'Regulatory scope.', gn: 'Alcance regulatorio.', pt: 'Alcance regulatório.' },
	'eudr.gate.scope': { es: 'El resultado es un análisis técnico, no una certificación formal bajo el Reglamento (UE) 2023/1115. La certificación regulatoria requiere además geometría parcelaria oficial, trazabilidad documental y due-diligence profesional independiente.', en: 'The result is a technical analysis, not a formal certification under Regulation (EU) 2023/1115. Regulatory certification also requires official plot geometry, documentary traceability and independent professional due diligence.', gn: 'El resultado es un análisis técnico, no una certificación formal bajo el Reglamento (UE) 2023/1115. La certificación regulatoria requiere además geometría parcelaria oficial, trazabilidad documental y due-diligence profesional independiente.', pt: 'O resultado é uma análise técnica, não uma certificação formal sob o Regulamento (UE) 2023/1115. A certificação regulatória requer ainda geometria oficial das parcelas, rastreabilidade documental e due diligence profissional independente.' },
	'eudr.gate.res.label': { es: 'Resolución del dato.', en: 'Data resolution.', gn: 'Resolución del dato.', pt: 'Resolução do dado.' },
	'eudr.gate.res': { es: 'La señal de pérdida está a 100 m y el área quemada proviene de un producto de 500 m, mayor que la celda evaluada. El resultado refleja el hexágono, no la parcela exacta — usalo como señal espacial robusta, no como medición catastral.', en: 'The loss signal is at 100 m and burned area comes from a 500 m product, larger than the cell assessed. The result reflects the hexagon, not the exact plot — use it as a robust spatial signal, not as a cadastral measurement.', gn: 'La señal de pérdida está a 100 m y el área quemada proviene de un producto de 500 m, mayor que la celda evaluada. El resultado refleja el hexágono, no la parcela exacta — usalo como señal espacial robusta, no como medición catastral.', pt: 'O sinal de perda está a 100 m e a área queimada vem de um produto de 500 m, maior que a célula avaliada. O resultado reflete o hexágono, não a parcela exata — use-o como sinal espacial robusto, não como medição cadastral.' },
	'eudr.gate.resp.label': { es: 'Responsabilidad.', en: 'Liability.', gn: 'Responsabilidad.', pt: 'Responsabilidade.' },
	'eudr.gate.resp': { es: 'Al continuar, aceptás que Spatia, su autor, CONICET y UNaM no asumen responsabilidad por decisiones comerciales o regulatorias basadas exclusivamente en este análisis.', en: 'By continuing, you accept that Spatia, its author, CONICET and UNaM accept no liability for commercial or regulatory decisions based solely on this analysis.', gn: 'Al continuar, aceptás que Spatia, su autor, CONICET y UNaM no asumen responsabilidad por decisiones comerciales o regulatorias basadas exclusivamente en este análisis.', pt: 'Ao continuar, você aceita que o Spatia, seu autor, o CONICET e a UNaM não assumem responsabilidade por decisões comerciais ou regulatórias baseadas exclusivamente nesta análise.' },
	'eudr.gate.ok': { es: 'Entendido — continuar con el análisis', en: 'Understood — continue to the analysis', gn: 'Entendido — continuar con el análisis', pt: 'Entendido — continuar com a análise' },
	'eudr.gate.source.label': { es: 'Fuente de cobertura.', en: 'Land-cover source.', gn: 'Fuente de cobertura.', pt: 'Fonte de cobertura.' },
	'eudr.gate.source.a': { es: 'MapBiomas – Colección 2 de la Serie Anual de Mapas de Cobertura y Uso del Suelo de Argentina, consultada el 24 de julio de 2026 a través del enlace:', en: 'MapBiomas – Collection 2 of the Annual Series of Land Cover and Land Use Maps of Argentina, accessed on 24 July 2026 at:', gn: 'MapBiomas – Colección 2 de la Serie Anual de Mapas de Cobertura y Uso del Suelo de Argentina, consultada el 24 de julio de 2026 a través del enlace:', pt: 'MapBiomas – Coleção 2 da Série Anual de Mapas de Cobertura e Uso do Solo da Argentina, consultada em 24 de julho de 2026 no endereço:' },
	'eudr.gate.source.b': { es: 'Pérdida de cobertura arbórea: Hansen/UMD Global Forest Change v1.13. Área quemada: NASA MODIS MCD64A1.', en: 'Tree cover loss: Hansen/UMD Global Forest Change v1.13. Burned area: NASA MODIS MCD64A1.', gn: 'Pérdida de cobertura arbórea: Hansen/UMD Global Forest Change v1.13. Área quemada: NASA MODIS MCD64A1.', pt: 'Perda de cobertura arbórea: Hansen/UMD Global Forest Change v1.13. Área queimada: NASA MODIS MCD64A1.' },
