	'rank.uso.title.monte': { es: '¿Cuánto monte nativo queda?', en: 'How much native forest is left?', gn: '¿Cuánto monte nativo queda?', pt: 'Quanta mata nativa resta?' },
	'rank.uso.title.plantacion': { es: '¿Dónde hay plantación forestal?', en: 'Where are the tree plantations?', gn: '¿Dónde hay plantación forestal?', pt: 'Onde há plantação florestal?' },
	'rank.uso.title.perenne': { es: '¿Dónde hay yerba, té y otros perennes?', en: 'Where are yerba mate, tea and other perennials?', gn: '¿Dónde hay yerba, té y otros perennes?', pt: 'Onde há erva-mate, chá e outras perenes?' },
	'rank.uso.title.agro': { es: '¿Dónde hay cultivo y pastura?', en: 'Where are crops and pasture?', gn: '¿Dónde hay cultivo y pastura?', pt: 'Onde há cultivo e pastagem?' },
	'rank.uso.title.monte85': { es: '¿Cuánto monte había en 1985?', en: 'How much forest was there in 1985?', gn: '¿Cuánto monte había en 1985?', pt: 'Quanta mata havia em 1985?' },
	'rank.uso.title.cambio': { es: '¿Cuánto monte se perdió desde 1985?', en: 'How much forest was lost since 1985?', gn: '¿Cuánto monte se perdió desde 1985?', pt: 'Quanta mata se perdeu desde 1985?' },
	'rank.uso.unit.pctMonte85': { es: '% del monte de 1985', en: '% of 1985 forest', gn: '% del monte de 1985', pt: '% da mata de 1985' },
	'rank.uso.note.monte': { es: '% de la superficie del departamento con monte nativo en 2025 (bosque cerrado, abierto e inundable de MapBiomas Argentina); al lado, las hectáreas. El mapa muestra la clase de cada hexágono. Clic en una barra para abrir el departamento.', en: 'Share of the department under native forest in 2025 (MapBiomas Argentina closed, open and flooded forest); beside it, hectares. The map shows each hexagon\'s class. Click a bar to open the department.', gn: '% de la superficie del departamento con monte nativo en 2025 (bosque cerrado, abierto e inundable de MapBiomas Argentina); al lado, las hectáreas. El mapa muestra la clase de cada hexágono. Clic en una barra para abrir el departamento.', pt: '% da área do departamento com mata nativa em 2025 (floresta fechada, aberta e alagável do MapBiomas Argentina); ao lado, os hectares. O mapa mostra a classe de cada hexágono. Clique numa barra para abrir o departamento.' },
	'rank.uso.note.plantacion': { es: 'Hectáreas de plantación forestal (pino, eucalipto, araucaria) en 2025; al lado, el % del departamento.', en: 'Hectares of tree plantation (pine, eucalyptus, araucaria) in 2025; beside it, share of the department.', gn: 'Hectáreas de plantación forestal (pino, eucalipto, araucaria) en 2025; al lado, el % del departamento.', pt: 'Hectares de plantação florestal (pinus, eucalipto, araucária) em 2025; ao lado, a % do departamento.' },
	'rank.uso.note.perenne': { es: '% del departamento con cultivos perennes en 2025: yerba, té y cítricos, que MapBiomas no separa. Sólo en %: marca de 2,8 a 3,3 veces la superficie plantada que registra el MAGyP, aunque ubica bien los departamentos yerbateros.', en: 'Share of the department under perennial crops in 2025: yerba mate, tea and citrus, which MapBiomas does not separate. Percent only: it maps 2.8–3.3 times the planted area recorded by MAGyP, though it locates the yerba departments well.', gn: '% del departamento con cultivos perennes en 2025: yerba, té y cítricos, que MapBiomas no separa. Sólo en %: marca de 2,8 a 3,3 veces la superficie plantada que registra el MAGyP, aunque ubica bien los departamentos yerbateros.', pt: '% do departamento com cultivos perenes em 2025: erva-mate, chá e cítricos, que o MapBiomas não separa. Só em %: marca de 2,8 a 3,3 vezes a área plantada registrada pelo MAGyP, embora localize bem os departamentos ervateiros.' },
	'rank.uso.note.agro': { es: 'Hectáreas de cultivo anual (soja, maíz, algodón, arroz, tabaco, mandioca) y pastura implantada en 2025; al lado, el % del departamento. Lotes de 1–3 ha, como muchas chacras de tabaco, quedan dentro del mosaico a 30 m.', en: 'Hectares of annual crops (soy, maize, cotton, rice, tobacco, cassava) and planted pasture in 2025; beside it, share of the department. Plots of 1–3 ha, like many tobacco farms, fall inside the mosaic at 30 m.', gn: 'Hectáreas de cultivo anual (soja, maíz, algodón, arroz, tabaco, mandioca) y pastura implantada en 2025; al lado, el % del departamento. Lotes de 1–3 ha, como muchas chacras de tabaco, quedan dentro del mosaico a 30 m.', pt: 'Hectares de cultivo anual (soja, milho, algodão, arroz, tabaco, mandioca) e pastagem plantada em 2025; ao lado, a % do departamento. Lotes de 1–3 ha, como muitas lavouras de tabaco, ficam dentro do mosaico a 30 m.' },
	'rank.uso.note.monte85': { es: '% del departamento con monte nativo en 1985; al lado, las hectáreas. El mapa muestra la clase de cada hexágono en 1985.', en: 'Share of the department under native forest in 1985; beside it, hectares. The map shows each hexagon\'s class in 1985.', gn: '% del departamento con monte nativo en 1985; al lado, las hectáreas. El mapa muestra la clase de cada hexágono en 1985.', pt: '% do departamento com mata nativa em 1985; ao lado, os hectares. O mapa mostra a classe de cada hexágono em 1985.' },
	'rank.uso.note.cambio': { es: 'Saldo de monte nativo entre 1985 y 2025 en hectáreas (positivo = se perdió, negativo = creció); al lado, como % del monte de 1985. Es el saldo del departamento, no la suma de las bajas de cada hexágono, que también suma el ruido de clasificación entre años. El mapa muestra qué pasó en cada hexágono.', en: 'Net change in native forest 1985–2025 in hectares (positive = lost, negative = grew); beside it, as % of the 1985 forest. It is the department\'s balance, not the sum of each hexagon\'s losses, which also adds classification noise between years. The map shows what happened in each hexagon.', gn: 'Saldo de monte nativo entre 1985 y 2025 en hectáreas (positivo = se perdió, negativo = creció); al lado, como % del monte de 1985. Es el saldo del departamento, no la suma de las bajas de cada hexágono, que también suma el ruido de clasificación entre años. El mapa muestra qué pasó en cada hexágono.', pt: 'Saldo de mata nativa entre 1985 e 2025 em hectares (positivo = perdeu-se, negativo = cresceu); ao lado, como % da mata de 1985. É o saldo do departamento, não a soma das perdas de cada hexágono, que também soma o ruído de classificação entre anos. O mapa mostra o que aconteceu em cada hexágono.' },
	'uso.serie.change': { es: 'Monte nativo: {m0} ha en {a} → {m1} ha en {b}. Plantación: {p0} → {p1} ha.', en: 'Native forest: {m0} ha in {a} → {m1} ha in {b}. Plantation: {p0} → {p1} ha.', gn: 'Monte nativo: {m0} ha en {a} → {m1} ha en {b}. Plantación: {p0} → {p1} ha.', pt: 'Mata nativa: {m0} ha em {a} → {m1} ha em {b}. Plantação: {p0} → {p1} ha.' },
	'uso.serie.aria': { es: 'Hectáreas por clase de uso del suelo cada 5 años', en: 'Hectares by land-use class every 5 years', gn: 'Hectáreas por clase de uso del suelo cada 5 años', pt: 'Hectares por classe de uso do solo a cada 5 anos' },
	'uso.serie.loading': { es: 'Cargando la serie…', en: 'Loading the series…', gn: 'Cargando la serie…', pt: 'Carregando a série…' },
	'uso.serie.note': { es: 'MapBiomas Argentina Colección 3 cada 5 años. Pasá el mouse por una barra para ver la clase y las hectáreas. Los cambios de un año a otro pueden ser ruido de clasificación; las tendencias de 40 años, no.', en: 'MapBiomas Argentina Collection 3 every 5 years. Hover a bar for the class and hectares. Year-to-year changes can be classification noise; 40-year trends are not.', gn: 'MapBiomas Argentina Colección 3 cada 5 años. Pasá el mouse por una barra para ver la clase y las hectáreas. Los cambios de un año a otro pueden ser ruido de clasificación; las tendencias de 40 años, no.', pt: 'MapBiomas Argentina Coleção 3 a cada 5 anos. Passe o mouse numa barra para ver a classe e os hectares. Mudanças de um ano a outro podem ser ruído de classificação; as tendências de 40 anos, não.' },

