	'analysis.accessibility.desc': { es: 'Minutos de viaje por camino a la capital, a ciudades de 50.000 habitantes o más, al hospital, al centro de salud, a la escuela secundaria y a la ruta principal — aislamiento por hexágono', en: 'Travel minutes by road to the capital, to cities of 50,000 or more, to a hospital, a health centre, a secondary school and the main road — isolation per hexagon', gn: "Aravo taviguasu peve, hospital, mbo'ehao ha tape", pt: 'Minutos de viagem por estrada até a capital, cidades de 50 mil habitantes ou mais, hospital, posto de saúde, escola de ensino médio e rodovia principal — isolamento por hexágono' },
