	'hexZone.personsEst': { es: 'Las personas se estiman desde los edificios: el error medido es de ~25 % por radio, y mayor en una zona chica.', en: 'People are estimated from buildings: the measured error is ~25 % per census tract, and larger in a small zone.', gn: 'Las personas se estiman desde los edificios: el error medido es de ~25 % por radio, y mayor en una zona chica.', pt: 'As pessoas são estimadas a partir dos edifícios: o erro medido é de ~25 % por setor, e maior numa zona pequena.' }, // gn: pendiente
	'hexZone.sharedN': { es: 'Cuando se compartió tenía {a} hexágonos; con los datos de hoy toma {b}.', en: 'When it was shared it had {a} hexagons; with today’s data it takes {b}.', gn: 'Cuando se compartió tenía {a} hexágonos; con los datos de hoy toma {b}.', pt: 'Quando foi compartilhada tinha {a} hexágonos; com os dados de hoje toma {b}.' }, // gn: pendiente
	'hexZone.chartNotInLink': { es: 'Las zonas guardadas desde un gráfico no viajan en el link: el link de esta página sólo lleva las del lazo.', en: 'Zones saved from a chart do not travel in the link: this page’s link only carries the lasso ones.', gn: 'Las zonas guardadas desde un gráfico no viajan en el link: el link de esta página sólo lleva las del lazo.', pt: 'As zonas salvas a partir de um gráfico não viajam no link: o link desta página só leva as do laço.' }, // gn: pendiente
